#!/usr/bin/env python3
"""
wag-server.py  —  Week at a Glance local server
Serves your calendar at http://localhost:8788
Handles Refresh button, and persists checkbox state across sessions.

State resets:
  - Daily non-negotiables (n1–n13): reset each morning automatically
  - Weekly tasks: reset every Monday automatically
  - State file: ~/Desktop/wag-state.json

Run once:  python3 ~/Desktop/wag-server.py
"""

import sqlite3, re, json, webbrowser, plistlib, glob, subprocess
from datetime import datetime, timezone, timedelta
from pathlib import Path
from http.server import HTTPServer, BaseHTTPRequestHandler

# ── Config ────────────────────────────────────────────────────────────────────
HTML_FILE   = Path.home() / "Desktop" / "week-at-a-glance.html"
STATE_FILE  = Path.home() / "Desktop" / "wag-state.json"
DUMP_FILE   = Path.home() / "Desktop" / "wag-braindump.json"
CONVO_LOG      = Path.home() / "Desktop" / "wag-conversations.json"
MESSENGER_JS   = Path.home() / "Desktop" / "wag-messenger.js"
NODE_BIN       = "/usr/local/bin/node"
MESSAGES_DB = Path.home() / "Library" / "Messages" / "chat.db"
PORT        = 8788
DAYS_BACK   = 7

# IDs that reset daily (not weekly)
DAILY_IDS = {
    'n1','n2','n3','n4','n5','n6','n7','n8','n9','n10','n11','n12','n13'
}

# ── State persistence ─────────────────────────────────────────────────────────
def week_key():
    """ISO week string, e.g. '2026-W23'. Resets weekly tasks on Monday."""
    return datetime.now().strftime("%Y-W%W")

def today_key():
    d = datetime.now()
    return f"{d.year}-{d.month}-{d.day}"

def load_state() -> dict:
    """Load state, auto-resetting stale weekly or daily buckets."""
    try:
        raw = json.loads(STATE_FILE.read_text())
    except Exception:
        raw = {}

    wk = week_key()
    td = today_key()

    # Reset weekly bucket if it's a new week
    if raw.get("week") != wk:
        print(f"[state] New week ({wk}) — resetting weekly tasks")
        raw["week"]   = wk
        raw["weekly"] = {}

    # Reset daily bucket if it's a new day
    if raw.get("today") != td:
        print(f"[state] New day ({td}) — resetting daily tasks")
        raw["today"] = td
        raw["daily"] = {}

    raw.setdefault("weekly", {})
    raw.setdefault("daily",  {})
    return raw

def save_state(state: dict):
    STATE_FILE.write_text(json.dumps(state, indent=2))

def get_checked() -> dict:
    """Return a flat {id: True} dict of all currently-checked tasks."""
    state = load_state()
    merged = {}
    merged.update({k: v for k, v in state["weekly"].items() if v})
    merged.update({k: v for k, v in state["daily"].items()  if v})
    return merged

def set_task(task_id: str, checked: bool):
    state = load_state()
    if task_id in DAILY_IDS:
        state["daily"][task_id] = checked
    else:
        state["weekly"][task_id] = checked
    save_state(state)
    bucket = "daily" if task_id in DAILY_IDS else "weekly"
    print(f"[toggle] {task_id} = {checked}  ({bucket})")

# ── Known contacts — loaded from macOS AddressBook at startup ─────────────────
CONTACTS = {}

def _norm_digits(num):
    d = re.sub(r'\D', '', num)
    if len(d) == 11 and d.startswith('1'):
        d = d[1:]
    return d if len(d) == 10 else None

def load_contacts():
    """Return {10-digit: 'First Last'} from all AddressBook sources."""
    result = {}
    pattern = str(Path.home() / "Library/Application Support/AddressBook/Sources/*/AddressBook-v22.abcddb")
    for db_path in glob.glob(pattern):
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            conn.row_factory = sqlite3.Row
            cur = conn.cursor()
            cur.execute("""
                SELECT r.ZFIRSTNAME, r.ZLASTNAME, r.ZORGANIZATION, p.ZFULLNUMBER
                FROM ZABCDRECORD r
                JOIN ZABCDPHONENUMBER p ON p.ZOWNER = r.Z_PK
                WHERE p.ZFULLNUMBER IS NOT NULL
            """)
            for r in cur.fetchall():
                first = (r['ZFIRSTNAME'] or '').strip()
                last  = (r['ZLASTNAME']  or '').strip()
                org   = (r['ZORGANIZATION'] or '').strip()
                name  = f"{first} {last}".strip() or org
                key   = _norm_digits(r['ZFULLNUMBER'] or '')
                if key and name and key not in result:
                    result[key] = name
            conn.close()
        except Exception:
            pass
    print(f"[contacts] loaded {len(result)} contacts")
    return result

