# ── Helpers ────────────────────────────────────────────────────────────────────
def fmt_phone(raw):
    """Return contact name if known, formatted number otherwise."""
    key = _norm_digits(raw)
    if key and key in CONTACTS:
        return CONTACTS[key]
    digits = re.sub(r"\D", "", raw)
    if len(digits) == 11 and digits.startswith("1"):
        digits = digits[1:]
    if len(digits) == 10:
        return f"({digits[:3]}) {digits[3:6]}-{digits[6:]}"
    # For emails, strip the domain for brevity
    if '@' in raw:
        local = raw.split('@')[0]
        known_emails = {'lilliangrace0628': 'Lily', '628lilygrace': 'Lily',
                        'thejoeshow72': 'Joe'}
        return known_emails.get(local, raw)
    return raw

def is_spam(sender, text):
    if sender in SPAM_SENDERS:
        return True
    t = text.lower()
    return any(re.search(p, t) for p in SPAM_PATTERNS)

def is_security(sender, text):
    if sender in SECURITY_SENDERS:
        return True
    t = text.lower()
    return any(re.search(p, t) for p in SECURITY_PATTERNS)

def extract_text(raw_content, attributed_body):
    """Return clean text from a message row, handling streamtyped attributedBody."""
    if raw_content and raw_content.strip():
        return raw_content.strip()
    if not attributed_body:
        return ''
    try:
        data = bytes(attributed_body)
        # Decode as latin-1 to preserve all bytes as characters
        text = data.decode('latin-1')
        # The actual message text in streamtyped format sits after all the
        # NS class name strings. Strip known noise tokens then grab what's left.
        noise_pattern = (
            r'streamtyped|NSAttributedString|NSMutableAttributedString|'
            r'NSMutableString|NSString|NSObject|NSColor|NSFont|NSDictionary|'
            r'NSParagraphStyle|NSArray|__kIM\w+|bplist\d+|YNSObject'
        )
        cleaned = re.sub(noise_pattern, ' ', text)
        # Keep only printable ASCII + common punctuation
        cleaned = re.sub(r'[^\x20-\x7e\n]', ' ', cleaned)
        cleaned = re.sub(r'\s+', ' ', cleaned).strip()
        # Find the first substantial readable run (>10 real words)
        # Split on long whitespace gaps and take the longest meaningful chunk
        chunks = [c.strip() for c in re.split(r'\s{2,}', cleaned) if len(c.strip()) > 8]
        # Filter out chunks that are mostly non-alpha (binary noise)
        good = [c for c in chunks if sum(ch.isalpha() for ch in c) / max(len(c),1) > 0.5]
        if good:
            result = good[0][:280]
            # Strip the full streamtyped class-name header if present
            result = re.sub(
                r'^.*?NS(?:Mutable)?(?:AttributedString|String|Object)\s*\+\s*[}]?',
                '', result, flags=re.DOTALL
            ).strip()
            # Strip any remaining leading artifacts
            result = re.sub(r'^[@\+\s\*\(\}]+', '', result).strip()
            # Truncate at binary garbage markers (anywhere they appear)
            for marker in ['iI i', 'iI (', 'iI &', 'NSNumber', ' iI\x00']:
                idx = result.find(marker)
                if idx >= 0:
                    result = result[:idx].strip()
            # Drop if too short after cleaning
            if len(result) < 3:
                return ''
            return result
    except Exception:
        pass
    return ''

def fetch_messages():
    cutoff = datetime.now(timezone.utc) - timedelta(days=DAYS_BACK)
    apple_cutoff = int((cutoff.timestamp() - 978307200) * 1e9)
    conn = sqlite3.connect(f"file:{MESSAGES_DB}?mode=ro", uri=True)
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    cur.execute("""
        SELECT
            m.text AS raw_text,
            m.attributedBody AS attr_body,
            datetime(m.date/1000000000 + 978307200, 'unixepoch', 'localtime') AS ts,
            h.id AS sender
        FROM message m
        INNER JOIN handle h ON h.ROWID = m.handle_id
        WHERE m.is_from_me = 0
          AND m.date >= ?
          AND (m.text IS NOT NULL OR m.attributedBody IS NOT NULL)
          AND m.is_audio_message = 0
          AND m.item_type = 0
        ORDER BY m.date DESC
        LIMIT 100
    """, (apple_cutoff,))
    raw_rows = cur.fetchall()
    rows = []
    for r in raw_rows:
        text = extract_text(r['raw_text'], r['attr_body'])
        if text:
            rows.append({'content': text, 'ts': r['ts'], 'sender': r['sender']})
    conn.close()
    return rows

def build_card(sender, text, ts, card_type, action=""):
    display = fmt_phone(sender)
    try:
        dt  = datetime.strptime(ts, "%Y-%m-%d %H:%M:%S")
        now = datetime.now()
        if dt.date() == now.date():
            day_label  = "Today"
            time_label = dt.strftime("%-I:%M %p")
        elif dt.date() == (now - timedelta(days=1)).date():
            day_label  = "Yesterday"
            time_label = dt.strftime("%-I:%M %p")
        else:
            day_label  = dt.strftime("%b %-d")
            time_label = dt.strftime("%-I:%M %p")
    except Exception:
        day_label, time_label = "", ts

    preview = text.strip().replace('"', '&quot;').replace('<', '&lt;').replace('>', '&gt;')
    if len(preview) > 180:
        preview = preview[:177] + "…"

    tag_class   = "security" if card_type == "imsg-alert" else ""
    action_html = f'<div class="ic-sub">{action}</div>' if action else ""

    return (
        f'<div class="inbox-card {card_type}">'
        f'<div class="ic-body">'
        f'<div class="ic-from">{display}'
        f'<span class="source-tag {tag_class}">iMessage · {day_label}</span></div>'
        f'<div class="ic-text">&ldquo;{preview}&rdquo;</div>'
        f'{action_html}'
        f'<div class="ic-time">{time_label}</div>'
        f'</div></div>'
    )

def is_conversational(text):
    """Return True if this message is casual back-and-forth with no action needed from Lauren."""
    t = text.lower().strip()
    words = t.split()

    # Standalone acknowledgements
    ack_phrases = {
        'ok','okay','k','sure','yeah','yes','yep','yup','no','nope','hmm','hm',
        'lol','haha','hehe','ha','omg','wow','nice','great','cool','thanks',
        'thank you','ty','np','no problem','got it','sounds good','will do',
        'on it','done','perfect','awesome','alright','noted','for sure',
        'of course','absolutely','definitely','exactly','right','true','agreed',
    }
    if t in ack_phrases:
        return True

    # Signals that the SENDER is taking action (not asking Lauren to do something)
    sender_doing = [
        r"\bi'?m\b",          # I'm, Im
        r"\bi'?ll\b",         # I'll
        r"\bi will\b",
        r"\bi'?ve\b",         # I've
        r"\bi just\b",
        r"\bima\b",           # Ima (AAVE: I'm going to)
        r"\bi went\b",
        r"\bi got\b",
        r"\bi called\b",
    ]

    # Signals that Lauren needs to do something
    directed_at_lauren = [
        r'\?',                                    # any question
        r'\b(can you|could you|would you|please)\b',
        r'\b(send me|text me|call me|let me know|tell me)\b',
        r'\bneed (to|you)\b',
        r'\b(confirm|appointment|appt|deadline|due date)\b',
        r'\b(pay|owe|balance|bill|invoice)\b',
        r'\b(pick up|drop off|bring|deliver)\b',
        r'\b(address|street|blvd|ave|drive|suite|zip)\b',
        r'\$\d',                                  # dollar amount
        r'\b\d{1,2}:\d{2}\b',                    # time
        r'\b(monday|tuesday|wednesday|thursday|friday|saturday|sunday)\b',
        r'\b(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)\b',
        r'\b(tomorrow|tonight|this week|next week|today)\b',
        r'https?://',
    ]

    has_direction = any(re.search(p, t) for p in directed_at_lauren)
    has_sender_action = any(re.search(p, t) for p in sender_doing)

    # If sender is describing their own action AND no direct ask → conversational
    if has_sender_action and not has_direction:
        return True

    # Short with no direction → conversational
    if len(words) <= 10 and not has_direction:
        return True

    return False

def log_conversation(sender, text, ts):
    """Append a conversational message to the conversations log."""
    try:
        try:
            log = json.loads(CONVO_LOG.read_text())
        except Exception:
            log = []
        log.append({
            "timestamp": ts,
            "sender": sender,
            "name": fmt_phone(sender),
            "text": text,
        })
        log = log[-200:]  # keep last 200
        CONVO_LOG.write_text(json.dumps(log, indent=2))
    except Exception as e:
        print(f"[convo log] error: {e}")

def week_start() -> str:
    """Return the Monday of the current week as YYYY-MM-DD."""
    today = datetime.now().date()
    monday = today - timedelta(days=today.weekday())
    return str(monday)

def nearest_weekday(target_date_str: str) -> str:
    """Return target date if it falls within this week, else today."""
    try:
        target = datetime.strptime(target_date_str, "%Y-%m-%d").date()
        monday = datetime.strptime(week_start(), "%Y-%m-%d").date()
        sunday = monday + timedelta(days=6)
        if monday <= target <= sunday:
            return target_date_str
    except Exception:
        pass
    return str(datetime.now().date())

def task_id(sender: str, text: str) -> str:
    """Stable short ID for a message-derived task."""
    import hashlib
    raw = (sender + text[:40]).encode()
    return "msg_" + hashlib.md5(raw).hexdigest()[:8]

def message_to_task(sender: str, text: str, ts: str) -> dict:
    """Convert an actionable message into a calendar task dict."""
    name    = fmt_phone(sender)
    t_lower = text.lower()
    today   = str(datetime.now().date())

    # Security alerts → today, urgent
    if is_security(sender, text):
        return {
            "id":     task_id(sender, text),
            "date":   today,
            "text":   f"⚠️ {name}: {text[:80]}",
            "urgent": True,
        }

    # Appointment reminders — assign to the day before the appointment
    appt_match = re.search(
        r'\b(\d{1,2})/(\d{1,2})\b|\b(monday|tuesday|wednesday|thursday|friday|saturday|sunday)\b'
        r'|\bjun(?:e)?\s+(\d{1,2})\b',
        t_lower
    )
    appt_date = today
    if appt_match:
        try:
            now = datetime.now()
            if appt_match.group(1):  # M/D format
                m, d = int(appt_match.group(1)), int(appt_match.group(2))
                candidate = datetime(now.year, m, d).date()
                day_before = candidate - timedelta(days=1)
                appt_date = nearest_weekday(str(day_before))
            elif appt_match.group(4):  # "Jun 8"
                d = int(appt_match.group(4))
                candidate = datetime(now.year, now.month, d).date()
                day_before = candidate - timedelta(days=1)
                appt_date = nearest_weekday(str(day_before))
        except Exception:
            appt_date = today

    if re.search(r'\bappointment\b|\bappt\b|\bscheduled\b', t_lower):
        return {
            "id":     task_id(sender, text),
            "date":   appt_date,
            "text":   f"📅 {name}: {text[:100]}",
            "urgent": False,
        }

    # Default: actionable message → today
    verb = "Reply to" if re.search(r'\?|send me|text me|call me|let me know|can you', t_lower) else "Follow up —"
    return {
        "id":     task_id(sender, text),
        "date":   today,
        "text":   f"{verb} {name}: {text[:90]}",
        "urgent": False,
    }

def fetch_messenger_tasks() -> list:
    """Run wag-messenger.js and return its task list (empty list on any failure)."""
    if not MESSENGER_JS.exists():
        return []
    try:
        result = subprocess.run(
            [NODE_BIN, str(MESSENGER_JS)],
            capture_output=True, text=True, timeout=35
        )
        if result.stderr:
            print(f"[messenger] {result.stderr.strip()[:200]}")
        if result.returncode != 0 or not result.stdout:
            return []
        data = json.loads(result.stdout)
        tasks = data.get("tasks", [])
        print(f"[messenger] {len(tasks)} task(s)")
        return tasks
    except Exception as e:
        print(f"[messenger] skipped: {e}")
        return []

def generate_tasks():
    """Parse messages and return a list of calendar task dicts."""
    messages = fetch_messages()
    tasks    = []
    seen     = set()
    sec_seen = set()

    for msg in messages:
        sender = msg["sender"]
        text   = msg["content"] or ""
        ts     = msg["ts"]

        if not text or len(text) < 5:
            continue
        if re.search(r'^iI i |^iI \(|NSNumber NSValue', text):
            continue
        if is_spam(sender, text):
            continue

        if is_security(sender, text):
            if sender not in sec_seen:
                sec_seen.add(sender)
                tasks.append(message_to_task(sender, text, ts))
            continue

        if sender in seen:
            continue
        seen.add(sender)

        if is_conversational(text):
            log_conversation(sender, text, ts)
            continue

        tasks.append(message_to_task(sender, text, ts))

    checked_at = datetime.now().strftime("%b %-d, %-I:%M %p")
    return tasks, checked_at

# ── HTTP handler ──────────────────────────────────────────────────────────────
class Handler(BaseHTTPRequestHandler):
    def log_message(self, fmt, *args):
        pass

    def _read_body(self) -> bytes:
        length = int(self.headers.get("Content-Length", 0))
        return self.rfile.read(length) if length else b""

    def _json(self, code, data):
        payload = json.dumps(data).encode()
        self.send_response(code)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", len(payload))
        self.end_headers()
        self.wfile.write(payload)

    def _err(self, code, msg):
        body = msg.encode()
        self.send_response(code)
        self.send_header("Content-Type", "text/plain")
        self.send_header("Content-Length", len(body))
        self.end_headers()
        self.wfile.write(body)

    def do_GET(self):
        if self.path in ("/", "/index.html"):
            try:
                body = HTML_FILE.read_bytes()
                self.send_response(200)
                self.send_header("Content-Type", "text/html; charset=utf-8")
                self.send_header("Content-Length", len(body))
                self.end_headers()
                self.wfile.write(body)
            except Exception as e:
                self._err(500, str(e))

        elif self.path == "/state":
            # Page calls this on load to restore checked state
            self._json(200, get_checked())

        else:
            self._err(404, "Not found")

    def do_POST(self):
        if self.path == "/refresh":
            try:
                imsg_tasks, checked_at = generate_tasks()
                fb_tasks = fetch_messenger_tasks()
                all_tasks = imsg_tasks + fb_tasks
                self._json(200, {"tasks": all_tasks, "checked_at": checked_at})
                print(f"[refresh] {checked_at} — {len(imsg_tasks)} iMessage + {len(fb_tasks)} Messenger task(s)")
            except Exception as e:
                self._err(500, str(e))

        elif self.path == "/braindump":
            try:
                body = json.loads(self._read_body())
                text = body.get("text", "").strip()
                ts   = body.get("timestamp", datetime.now().isoformat())
                if not text:
                    self._err(400, "empty dump")
                    return
                # Load existing dumps, append new one
                try:
                    dumps = json.loads(DUMP_FILE.read_text())
                except Exception:
                    dumps = []
                dumps.append({"timestamp": ts, "text": text})
                # Keep last 30 days of dumps
                dumps = dumps[-30:]
                DUMP_FILE.write_text(json.dumps(dumps, indent=2))
                print(f"[braindump] saved {len(text)} chars at {ts[:10]}")
                self._json(200, {"ok": True, "saved": ts})
            except Exception as e:
                self._err(500, str(e))

        elif self.path == "/toggle":
            # Body: {"id": "t0", "checked": true}
            try:
                body = json.loads(self._read_body())
                task_id = body["id"]
                checked = bool(body["checked"])
                set_task(task_id, checked)
                self._json(200, {"ok": True})
            except Exception as e:
                self._err(400, str(e))

        else:
            self._err(404, "Not found")

# ── Main ──────────────────────────────────────────────────────────────────────
if __name__ == "__main__":
    # Load contacts and state on startup
    CONTACTS.update(load_contacts())
    load_state()
    url = f"http://localhost:{PORT}"
    print(f"Week at a Glance  →  {url}")
    print(f"State file: {STATE_FILE}")
    print("Press Ctrl+C to stop.\n")
    webbrowser.open(url)
    HTTPServer(("localhost", PORT), Handler).serve_forever()
